function pw(a, b) {
    let c = b;
    let d = a;
    let res = 1n;
    while (c > 0n) {
        if ((c & 1n) !== 0n) {
            res = (res * d) % mod;
        }
        d = (d * d) % mod;
        c = c >> 1n;
    }
    return res;
}

function inv(a) {
    return pw(a, mod - 2n);
}

